                // the human-readable part that follows them.
                const iconMatch = raw.match(/^([^\p{L}\p{N}]+)(\s+)(.+)$/u);
                if (iconMatch && sourceIndex.has(iconMatch[3])) {
                    key = iconMatch[3];
                    node.__raydroneI18nPrefix = `${iconMatch[1]}${iconMatch[2]}`;
                }
